/** Was gemalt ist - der wirkliche Vorrat. */
export const gemalt = () => TIERE.filter(t => t.bild);

/** Ein Stueck an seiner Kennung. */
export const tierMit = (id) => TIERE.find(t => t.id === id) || null;

/** Der Lebensraum einer Ebene - oder `null`, wenn sie keinen hat. */
export const raumZu = (ebeneId) =>
  (ebeneId && RAEUME.find(r => (r.ebenen || []).includes(ebeneId))) || null;

/**
 * Welcher Raum sich durch die SAMMLUNG oeffnet (T6).
 *
 * Geprueft wird gegen das, was das Kind schon hat - nicht gegen eine
 * Zahl im Stand. Ein Zaehler waere eine zweite Wahrheit neben `ids`
 * (Regel 6), und er liefe auseinander, sobald ein Tier auf einem
 * anderen Geraet dazukommt.
 *
 * Gibt hoechstens EINEN Raum zurueck, auch wenn zwei Schwellen zugleich
 * faellig waeren: der Endbildschirm hat eine Zeile, und zwei Nachrichten
 * auf einmal sind fuer ein sechsjaehriges Kind keine zwei Nachrichten,
 * sondern keine.
 */
export function raumAbZahl(habe = []) {
  const da = new Set(habe);
  for (const r of RAEUME) {
    if (!r.ab || da.size < r.ab) continue;
    const neu = r.tiere.map(tierMit).filter(t => t && t.bild && !da.has(t.id));
    if (neu.length) return { raum: r, neu };
  }
  return null;
}

/**
 * Was das Fertigwerden DIESER Ebene einbringt - nur, was gemalt ist und
 * noch fehlt.
 *
 * Ein Raum, dessen Bilder noch nicht da sind, gibt nichts; er
 * verschwindet aber nicht, sondern wartet. Waere es umgekehrt - eine
 * Kennung ohne Bild im Stand -, stuende im Buch ein leeres Kaestchen mit
 * einem Namen, und niemand wuesste, ob das ein Fehler ist.
 */
export function raumTiere(ebeneId, habe = []) {
  const r = raumZu(ebeneId);
  if (!r) return [];
  const da = new Set(habe);
  return r.tiere.map(tierMit).filter(t => t && t.bild && !da.has(t.id));
}

/**
 * Der naechste Raum, den die SAMMLUNG oeffnet - und wieviele Tiere noch
 * fehlen (I18).
 *
 * Gemessen: von Leas vierzig Ebenen zahlen sechsundzwanzig nichts. Neun
 * Hauptstadtebenen fuehren in EINE Stadt, zehn Flaggenebenen in EINEN
 * Vogelpark, sieben Englischebenen in EIN Riff - wer die zweite fertig
 * macht, bekommt nichts und hoert nichts. Der Endbildschirm sagt „Gut
 * gemacht" und sonst gar nichts, und das ist die Stelle, an der ein Kind
 * aufhoert zu fragen, wofuer es das tut.
 *
 * Der Lohn wird deshalb nicht groesser, sondern SICHTBAR: was es nicht
 * mehr zu holen gibt, wird zu dem, was als naechstes zu holen ist. Und
 * das gibt es wirklich - die beiden Raeume mit Schwelle sind der Lohn
 * fuer das Sammeln selbst.
 *
 * `null` heisst: es ist alles geholt. Auch das ist eine Auskunft, und
 * eine bessere als Schweigen.
 */
export function naechsteSchwelle(habe = []) {
  const da = new Set(habe);
  let naechste = null;
  for (const r of RAEUME) {
    if (!r.ab) continue;
    /* Ein Raum, dessen Tiere schon alle da sind, ist keine Schwelle mehr
       - auch wenn eine spaetere noch offen ist. Deshalb weiter und nicht
       abbrechen. */
    if (r.tiere.every(id => da.has(id))) continue;
    /* Und ein Raum, dessen Schwelle schon ERREICHT ist, ist auch keine:
       er ist faellig und wird von `raumAbZahl` vergeben. Der erste
       Anlauf schrieb hier `Math.max(1, ...)` und sagte damit „noch ein
       Tier" ueber einen Raum, der laengst zu haben war - eine Zahl, die
       nicht luegen darf, weil ein Kind sie zaehlt. */
    if (r.ab <= da.size) continue;
    /* Und gesucht wird die KLEINSTE offene Schwelle, nicht die erste in
       der Liste. Bis I20 waren es zwei Raeume, und sie standen in der
       richtigen Reihenfolge da - mit acht ist „steht richtig in der
       Liste" keine Eigenschaft mehr, auf die sich etwas verlassen
       darf. Wer einen Raum an die falsche Stelle setzt, bekaeme sonst
       einen Satz, der eine spaetere Schwelle als naechste ausgibt, und
       nichts waere rot. */
    if (!naechste || r.ab < naechste.ab) naechste = r;
  }
  return naechste ? { raum: naechste, fehlt: naechste.ab - da.size } : null;
}

/** Alles, was ueberhaupt zu sammeln ist: die Tiere der Raeume, gemalt. */
export const sammelbar = () => {
  const ids = new Set(RAEUME.flatMap(r => r.tiere));
  return gemalt().filter(t => ids.has(t.id) && t.id !== GORILLA);
};


/* ---------- Die Kulissen (T2) -----------------------------------------
 *
 * Eine je LEBENSRAUM, nicht je Ebene: „In der Stadt" haengt an zwei
 * Ebenen und ist EINE Landschaft. Der Schluessel ist deshalb der Titel
 * des Raumes - dieselbe Einheit, in der auch gesammelt wird.
 *
 * DER RAHMEN IST 160 x 90 und nicht 48 x 48 wie beim Tier: eine
 * Landschaft ist breit, ein Aufkleber ist quadratisch. Der Horizont
 * liegt bei y=34; darunter beginnt das Spielfeld, ueber das die neun
 * Plaetze gelegt werden.
 *
 * DESHALB STEHT IN DER MITTE NICHTS. Baeume, Felsen und Haeuser stehen
 * am RAND - was in der Mitte steht, verdeckt einen Platz, und ein
 * Platz, auf dem ein Baum waechst, ist kein Platz. Das ist die einzige
 * Regel, die diese zehn Bilder gemeinsam haben.
 *
 * Sonst gilt, was fuer die Tiere gilt: nur Pfade, kein `transform`,
 * keine Datei - aus demselben Grund (`passt` misst je Pfad, und die App
 * ist EINE Datei).
 *
 * `ton` ist der Grund, auf dem die Szene liegt - fuer den Rahmen und
 * fuer die Kachel, die ins Bild fuehrt. Er gehoert zur Landschaft wie
 * der Aufkleberton zum Tier.
 */
export const SZENE = '0 0 160 90';

/** So viele Plaetze hat jede Landschaft: drei Reihen zu dreien.
 *
 *  Nicht mehr: auf 390 Punkten Breite - der schmalsten Groesse, die
 *  `passt` faehrt - ist eine Spalte dann noch 120 Punkte breit. Vier
 *  Spalten waeren 90, und die hinterste Reihe faellt damit unter das
 *  Fingermass. Die Zahl kommt aus der Messung, nicht aus dem Gefuehl. */
export const PLAETZE = 9;

